// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;
    bool jojoDirectSuccess;
    bool otherDirectSuccess;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _test(address unauthorised, string memory description) internal {
        vm.assume(unauthorised != c.jojoTeam());
        vm.assume(msg.sender == c.jojoTeam());
        vm.assume(unauthorised != address(0));
        jojoDirectSuccess = false;
        otherDirectSuccess = false;
        c.newEmergencyOracle(description);
        jojoDirectSuccess = true;
        try c.newEmergencyOracle(description) {
            otherDirectSuccess = true;
        } catch {}
        assertTrue(jojoDirectSuccess == true && otherDirectSuccess == false);
    }

    function testFuzz_test(address unauthorised, string memory description) public {
        vm.assume(unauthorised.code.length == 0 && uint160(unauthorised) > 0xffff && unauthorised != address(this) && unauthorised != address(c) && unauthorised != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && unauthorised != 0x000000000000000000636F6e736F6c652e6c6f67 && unauthorised != 0x4e59b44847b379578588920cA78FbF26c0B4956C && unauthorised != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(unauthorised, description);
    }
}
